CustomField.formula:
IF( ISPICKVAL(TSGCFG__Consolidation_Method__c, 'Average') && TSGCFG__PrinterTotalCPCLineItem__c > 0,
TSGCFG__PrinterSumofCPCBW__c / TSGCFG__PrinterTotalCPCLineItem__c ,
IF( ABS(TSGCFG__PrinterTotalMonoVolume__c - TSGCFG__PrinterTotalVolumeIncludesBW__c) <>0, TSGCFG__Printer_Total_BW_Monthly_Cost__c / ABS(TSGCFG__PrinterTotalMonoVolume__c - TSGCFG__PrinterTotalVolumeIncludesBW__c),
IF(TSGCFG__PrinterTotalCPCLineItem__c > 0, TSGCFG__PrinterSumofCPCBW__c / TSGCFG__PrinterTotalCPCLineItem__c, 0)
)
)
